// Фикстура для test-worker-watchdog.test.mjs.
// Тест проходит, но оставляет за собой бесконечный polling-цикл: ровно тот класс
// утечки, из-за которого воркер `node --test` не выходит, а весь набор висит без
// отчёта. Не подпадает под глоб `src/tests/*.test.mjs` — в набор не попадает.
import { it } from 'node:test';

it('проходит, но оставляет незавершённый polling-цикл', () => {
  // Никто не await-ит и не отменяет: ручка таймера живёт после конца теста.
  (async () => {
    for (;;) {
      await new Promise(resolve => setTimeout(resolve, 50));
    }
  })();
});
